-- MelloUI Languages: Français (frFR). The configurator's and the installer's lines, English -> Français.
-- Written by Tools/languages/languages.py from the addon's English and the translations; a line ending in
-- "-- draft" is a machine draft no translator has checked yet. A line missing here shows in English.
local Lang = MelloUI and MelloUI.Lang
if not (Lang and Lang:Wants("frFR")) then
	return
end
Lang:Add("frFR", {
	-- UIModifications
	["UI Modifications"] = "Réglages UI", -- draft
	["The painted kit reskin, area by area, and the interface's features: buffs and debuffs, error messages, cooldowns, unit frames, chat, tooltips, fonts, dark mode and more. The look is chosen on the Look page and on each element's own page."] = "L'habillage peint du kit, zone par zone, et les fonctions de l'interface : améliorations et affaiblissements, messages d'erreur, temps de recharge, portraits d'unités, discussion, encadrés d'aide, polices, mode sombre et plus encore. L'apparence se choisit sur la page Apparence et sur la page de chaque élément.", -- draft
	["The painted reskin, area by area, and the quality-of-life tweaks on nameplates, tooltips, chat and unit frames. Start here."] = "L'habillage peint, zone par zone, et les améliorations de confort des barres d'info, des encadrés d'aide, de la discussion et des portraits d'unités. Commencez ici.", -- draft
	["Painted Kit Reskin"] = "Habillage peint du kit", -- draft
	["The game's windows and HUD dressed in the painted kit, and the frame of MelloUI's own windows. Off: the game's windows and HUD keep the game's own art; MelloUI's own parts (the Quest Tracker, the widget column, the reminders, the race bar ...) keep MelloUI's look either way, and every feature keeps working. Switching it on also switches Custom Sounds on, and the first time puts in the Edit Mode layout the reskin is drawn for, fitted to your screen. Switching it off leaves Custom Sounds on."] = "Les fenêtres et l'ATH du jeu habillés du kit peint, ainsi que le cadre des fenêtres de MelloUI. Désactivé : les fenêtres et l'ATH du jeu gardent leurs propres graphismes ; les éléments de MelloUI (le suivi des quêtes, la colonne de widgets, les rappels, la barre de course...) gardent l'apparence de MelloUI dans tous les cas, et chaque fonction continue de marcher. L'activer active aussi les Sons personnalisés et, la première fois, installe la disposition du mode Édition pour laquelle l'habillage est dessiné, ajustée à votre écran. Le désactiver laisse les Sons personnalisés activés.", -- draft
	["Preload Artwork"] = "Précharger les graphismes", -- draft
	["Load all of the reskin's artwork during the loading screen, so a window opened for the first time after a reload shows its art at once instead of a moment later. Keeps about 13 MB of artwork in memory for the whole session, including for windows you never open. Off: each piece loads the first time a window needs it."] = "Charge tous les graphismes de l'habillage pendant l'écran de chargement, pour qu'une fenêtre ouverte pour la première fois après un rechargement affiche ses graphismes immédiatement plutôt qu'un instant plus tard. Garde environ 13 Mo de graphismes en mémoire toute la session, y compris pour les fenêtres que vous n'ouvrez jamais. Désactivé : chaque élément se charge la première fois qu'une fenêtre en a besoin.", -- draft
	["Switch every area on"] = "Activer toutes les zones", -- draft
	["Every window and HUD area of the reskin back on, and every feature of UI Modifications that is on by default."] = "Réactive chaque zone de fenêtre et d'ATH de l'habillage, ainsi que chaque fonction des Réglages UI activée par défaut.", -- draft
	["when nothing is reskinned any more"] = "quand plus rien n'est habillé", -- draft
	["Switch on"] = "Activer", -- draft
	["Palette"] = "Palette", -- draft
	["The painted reskin's colours: its art, and MelloUI's own windows and parts while it dresses. Without it MelloUI wears its modern palette, Gilded Slate. Your choice applies at once."] = "Les couleurs de l'habillage peint : ses graphismes, ainsi que les fenêtres et éléments de MelloUI tant qu'il les habille. Sans lui, MelloUI porte sa palette moderne, Gilded Slate. Votre choix s'applique immédiatement.", -- draft
	["Ember"] = "Ember", -- draft
