	["Obsidian"] = "Obsidian", -- draft
	["Neutral black glass and pewter, cold white text, one crimson accent. The calmest, highest-contrast base."] = "Verre noir neutre et étain, texte blanc froid, un accent cramoisi. La base la plus calme et la plus contrastée.", -- draft
	["Obsidian Vibrant"] = "Obsidian Vibrant", -- draft
