	["Cooldown Manager"] = "Gestionnaire de temps de recharge", -- draft
	["Icon frames and bar backgrounds of the Essential, Utility and Buff cooldown viewers."] = "Les cadres d'icône et les fonds de barre des affichages de temps de recharge essentiels, utilitaires et des améliorations.", -- draft
	["Micro Menu & Bag Bar"] = "Micro-menu et barre de sacs", -- draft
