	-- Nameplates
	["Large crowd-control icon above the name and a quest marker on enemy nameplates."] = "Une grande icône de contrôle au-dessus du nom et un marqueur de quête sur les barres d'info ennemies.", -- draft
	["Know who is stunned, who is your quest target, and who is about to be a problem."] = "Sachez qui est étourdi, qui est votre cible de quête, et qui va poser problème.", -- draft
	["Crowd Control"] = "Contrôle des foules", -- draft
	["Large CC Icon Above Name"] = "Grande icône de contrôle au-dessus du nom", -- draft
	["Move the crowd-control icon from the right side of the nameplate to above the name and enlarge it. Requires Blizzard's Crowd Control nameplate aura option to be on."] = "Déplace l'icône de contrôle du côté droit de la barre d'info au-dessus du nom et l'agrandit. Nécessite l'option d'aura de contrôle des barres d'info de Blizzard activée.", -- draft
