	["Quest Icon"] = "Icône de quête", -- draft
	["Show a yellow quest marker left of the health bar on enemies that still count for one of your quests."] = "Affiche un marqueur de quête jaune à gauche de la barre de vie des ennemis qui comptent encore pour l'une de vos quêtes.", -- draft
	["Quest Icon Size"] = "Taille de l'icône de quête", -- draft
