	["What lies behind the health bar: a flat colour (Background Colour), one of MelloUI's backgrounds (stone, concrete, parchment, the dark gradients...), or none."] = "Ce qui se trouve derrière la barre de vie : une couleur unie (Couleur de fond), l'un des fonds de MelloUI (pierre, béton, parchemin, les dégradés sombres...), ou rien.", -- draft
	["Flat colour"] = "Couleur unie", -- draft
	["Background Colour"] = "Couleur de fond", -- draft
	["The colour behind the health bar: one of yours, or the member's class colour."] = "La couleur derrière la barre de vie : l'une des vôtres, ou la couleur de classe du membre.", -- draft
	["Class Colour"] = "Couleur de classe", -- draft
	["My Background Colour"] = "Ma couleur de fond", -- draft
