	["Power Colour"] = "Couleur de la ressource", -- draft
	["The power bar's colour: the power's own (blue mana, red rage, yellow energy), the member's class colour, or one of yours."] = "La couleur de la barre de ressource : celle de la ressource (mana bleu, rage rouge, énergie jaune), la couleur de classe du membre, ou l'une des vôtres.", -- draft
	["Power Type"] = "Type de ressource", -- draft
	["My Power Colour"] = "Ma couleur de ressource", -- draft
