	["The face of the names on your party and raid frames. Shared: the Interface text's face (Look > Fonts)."] = "La police des noms sur vos cadres de groupe et de raid. Partagée : la police du Texte de l'interface (Apparence > Polices).", -- draft
	["Health Text Font"] = "Police du texte de vie", -- draft
